Implement authentication and ensure only authorized users can access sensitive data.

```javascript
const express = require('express');
const app = express();

// Middleware to check authentication
const authenticate = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  // This is a placeholder - use proper JWT, session, or API key validation
  if (!authHeader || !isValidApiKey(authHeader)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
};

function isValidApiKey(header) {
