  ]);
});
```

### 6. Missing CORS Configuration

The application allows requests from any origin by default, which could enable cross-site request forgery.

**Recommendation:**
Explicitly configure CORS.

```javascript
const cors = require('cors');

// Configure CORS for specific domains in production
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));
```

